/* Native interaction-grammar compiler.  A donor grammar has no people,
 * messages, media, rights, payments or effects. It is addressable only after
 * a binding attaches it to an exact native owner and subject coordinate. */
#define _POSIX_C_SOURCE 200809L
#include <sqlite3.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct { const char *id,*donor,*family,*application,*operation,*extent,*verifier,*lowerer,*owner_family; } Grammar;
static const Grammar GRAMMARS[] = {
 {"youtube-creator-channel","YouTube","creator-channel","media","watch","page","CreatorChannel:visibility","ChannelSurfaceCompiler:surface","CreatorChannel"},
 {"discord-community","Discord","realtime-community","community","communicate","workspace","Community:conversation_visibility","CommunitySurfaceCompiler:conversation","Community"},
 {"microsoft-teams-workspace","Microsoft Teams","institution-workspace","workspace","collaborate","workspace","Workspace:member_scope","WorkspaceCompiler:workspace","WorkGraph"},
 {"slack-workstream","Slack","workstream-canvas","workspace","collaborate","workspace","Workspace:member_scope","WorkspaceCompiler:workstream","WorkGraph"},
 {"facebook-social-body","Facebook","social-graph-group","community","discover","page","RelationshipGraph:audience","SocialSurfaceCompiler:feed","RelationshipGraph"},
 {"reddit-topic-community","Reddit","topic-thread-moderation","community","communicate","page","Community:public_body","CommunitySurfaceCompiler:thread","Community"},
 {"twitch-live-stage","Twitch","live-creator-stage","media","stream","page","Stage:admission","StageCompiler:live","Stage"},
 {"tiktok-short-stream","TikTok","short-media-discovery","media","watch","page","CreatorChannel:visibility","ChannelSurfaceCompiler:shorts","CreatorChannel"},
 {"instagram-identity-media","Instagram","identity-media-story","media","discover","page","RelationshipGraph:audience","SocialSurfaceCompiler:story","RelationshipGraph"},
 {"whatsapp-private-correspondence","WhatsApp","private-correspondence","correspondence","communicate","workspace","Correspondence:participant_scope","CorrespondenceCompiler:thread","Correspondence"},
 {"telegram-community-broadcast","Telegram","group-broadcast-bot","community","communicate","workspace","Community:conversation_visibility","CommunitySurfaceCompiler:broadcast","Community"},
 {"github-collaborative-code","GitHub","artifact-review-work","work","review","workspace","WorkGraph:participant_scope","WorkGraphCompiler:review","WorkGraph"},
 {"notion-knowledge-workspace","Notion","document-database","knowledge","compose","workspace","KnowledgeGraph:workspace_scope","KnowledgeCompiler:workspace","KnowledgeGraph"},
 {"linear-project-flow","Linear","issue-cycle-roadmap","work","plan","workspace","WorkGraph:participant_scope","WorkGraphCompiler:cycle","WorkGraph"},
 {"jira-project-service","Jira","issue-service-workflow","work","triage","workspace","WorkGraph:participant_scope","WorkGraphCompiler:service","WorkGraph"},
 {"figma-design-collaboration","Figma","design-artifact-review","artifact","review","workspace","ArtifactGraph:access","ArtifactCompiler:design_review","ArtifactGraph"},
 {"spotify-audio-habitat","Spotify","audio-library-playlist","media","listen","page","MediaLibrary:access","MediaLibraryCompiler:listen","MediaLibrary"},
 {"pinterest-visual-board","Pinterest","visual-save-board","collection","collect","page","WorldPublication:published","BoardCompiler:visual_collection","WorldPublication"},
 {"shopify-merchant-commerce","Shopify","catalog-cart-order","commerce","purchase","page","Offer:current_terms","CommerceCompiler:offer","Offer"},
 {"airbnb-place-reservation","Airbnb","place-reservation-trip","reservation","reserve","page","ProtocolContract:admission","ProtocolCompiler:reservation","ProtocolContract"}
};
static const size_t GRAMMAR_COUNT=sizeof(GRAMMARS)/sizeof(GRAMMARS[0]);
/* All twenty grammars are consumed by this one native compiler boundary.
 * `Grammar.lowerer` is the next typed surface compiler, not an assertion that
 * that compiler has run.  Keeping the consumer reference stable means the
 * AddressPlane can route every grammar through a real worker without turning
 * donor names into executable endpoints. */
#define INTERACTION_CONSUMER "InteractionGrammarCompiler:surface"
static const char*arg(int ac,char**av,const char*k){int i;for(i=2;i+1<ac;i++)if(!strcmp(av[i],k))return av[i+1];return NULL;}
static int atom(const char*s){const unsigned char*p=(const unsigned char*)s;size_t n=0;if(!s||!*s)return 0;for(;*p;p++,n++)if(n>=255||!((*p>='a'&&*p<='z')||(*p>='A'&&*p<='Z')||(*p>='0'&&*p<='9')||*p==':'||*p=='-'||*p=='_'||*p=='.'||*p=='/'))return 0;return 1;}
static void js(const char*s){const unsigned char*p=(const unsigned char*)(s?s:"");putchar('"');for(;*p;p++){if(*p=='"'||*p=='\\'){putchar('\\');putchar(*p);}else if(*p<32)printf("\\u%04x",*p);else putchar(*p);}putchar('"');}
static void term(int *first,const char *axis,const char *value){char out[256];size_t i=0;int dash=0;const unsigned char*p=(const unsigned char*)(value?value:"");for(;*p&&i+1<sizeof(out);p++){unsigned char c=*p;if((c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')){out[i++]=(char)((c>='A'&&c<='Z')?c+32:c);dash=0;}else if(i&&!dash){out[i++]='-';dash=1;}}while(i&&out[i-1]=='-')i--;if(!i)out[i++]='x';out[i]=0;if(!*first)putchar(',');*first=0;putchar('"');fputs(axis,stdout);putchar(':');fputs(out,stdout);putchar('"');}
static int sql(sqlite3*d,const char*q){char*e=NULL;int ok=sqlite3_exec(d,q,NULL,NULL,&e)==SQLITE_OK;if(!ok){fprintf(stderr,"sqlite: %s\n",e?e:"error");sqlite3_free(e);}return ok;}
static int has_column(sqlite3*d,const char*table,const char*column){sqlite3_stmt*s=0;char q[128];int ok=0;snprintf(q,sizeof(q),"PRAGMA table_info(%s)",table);if(sqlite3_prepare_v2(d,q,-1,&s,0)!=SQLITE_OK)return 0;while(sqlite3_step(s)==SQLITE_ROW){const char*n=(const char*)sqlite3_column_text(s,1);if(n&&!strcmp(n,column)){ok=1;break;}}sqlite3_finalize(s);return ok;}
static int open_db(const char*p,sqlite3**d){sqlite3_stmt*s=NULL;size_t i;if(!p||sqlite3_open_v2(p,d,SQLITE_OPEN_READWRITE|SQLITE_OPEN_CREATE,NULL)!=SQLITE_OK)return 0;sqlite3_busy_timeout(*d,5000);if(!sql(*d,"PRAGMA journal_mode=WAL;CREATE TABLE IF NOT EXISTS interaction_grammar_catalog(grammar_id TEXT PRIMARY KEY,donor_reference TEXT NOT NULL,family TEXT NOT NULL,application TEXT NOT NULL,operation TEXT NOT NULL,extent TEXT NOT NULL,exact_verifier TEXT NOT NULL,lowerer_ref TEXT NOT NULL,owner_family TEXT NOT NULL);CREATE TABLE IF NOT EXISTS interaction_grammar_binding(binding_id TEXT PRIMARY KEY,grammar_id TEXT NOT NULL REFERENCES interaction_grammar_catalog(grammar_id),subject_ref TEXT NOT NULL,institution_ref TEXT NOT NULL DEFAULT '',owner_ref TEXT NOT NULL,visibility TEXT NOT NULL CHECK(visibility IN('public','member','private')),state TEXT NOT NULL CHECK(state IN('active','retired')),updated_at INTEGER NOT NULL,source_kind TEXT NOT NULL DEFAULT 'manual',source_ref TEXT NOT NULL DEFAULT '');CREATE INDEX IF NOT EXISTS interaction_grammar_active ON interaction_grammar_binding(grammar_id,state,subject_ref);"))return 0;if(!has_column(*d,"interaction_grammar_binding","source_kind")&&!sql(*d,"ALTER TABLE interaction_grammar_binding ADD COLUMN source_kind TEXT NOT NULL DEFAULT 'manual'"))return 0;if(!has_column(*d,"interaction_grammar_binding","source_ref")&&!sql(*d,"ALTER TABLE interaction_grammar_binding ADD COLUMN source_ref TEXT NOT NULL DEFAULT ''"))return 0;if(sqlite3_prepare_v2(*d,"INSERT INTO interaction_grammar_catalog VALUES(?1,?2,?3,?4,?5,?6,?7,?8,?9) ON CONFLICT(grammar_id) DO UPDATE SET donor_reference=excluded.donor_reference,family=excluded.family,application=excluded.application,operation=excluded.operation,extent=excluded.extent,exact_verifier=excluded.exact_verifier,lowerer_ref=excluded.lowerer_ref,owner_family=excluded.owner_family",-1,&s,NULL)!=SQLITE_OK)return 0;for(i=0;i<GRAMMAR_COUNT;i++){const Grammar*g=&GRAMMARS[i];sqlite3_bind_text(s,1,g->id,-1,SQLITE_STATIC);sqlite3_bind_text(s,2,g->donor,-1,SQLITE_STATIC);sqlite3_bind_text(s,3,g->family,-1,SQLITE_STATIC);sqlite3_bind_text(s,4,g->application,-1,SQLITE_STATIC);sqlite3_bind_text(s,5,g->operation,-1,SQLITE_STATIC);sqlite3_bind_text(s,6,g->extent,-1,SQLITE_STATIC);sqlite3_bind_text(s,7,g->verifier,-1,SQLITE_STATIC);sqlite3_bind_text(s,8,g->lowerer,-1,SQLITE_STATIC);sqlite3_bind_text(s,9,g->owner_family,-1,SQLITE_STATIC);if(sqlite3_step(s)!=SQLITE_DONE){sqlite3_finalize(s);return 0;}sqlite3_reset(s);sqlite3_clear_bindings(s);}sqlite3_finalize(s);return 1;}
static const Grammar*grammar(const char*id){size_t i;for(i=0;i<GRAMMAR_COUNT;i++)if(!strcmp(GRAMMARS[i].id,id))return &GRAMMARS[i];return NULL;}
/* A grammar does not get to nominate an arbitrary owner family.  This is not
 * authentication (the owning compiler must still authenticate its actor), but
 * it stops a `Community` grammar being forwarded as a `Finance` or invented
 * owner boundary before that compiler ever receives a handoff. */
static int owner_family_matches(const Grammar*g,const char*owner){size_t n;if(!g||!owner)return 0;n=strlen(g->owner_family);return !strncmp(owner,g->owner_family,n)&&owner[n]==':';}
static void print_grammar(const Grammar*g){fputs("{\"schema\":\"bonfyre-interaction-grammar.v1\",\"id\":",stdout);js(g->id);fputs(",\"donor_reference\":",stdout);js(g->donor);fputs(",\"family\":",stdout);js(g->family);fputs(",\"application\":",stdout);js(g->application);fputs(",\"operation\":",stdout);js(g->operation);fputs(",\"extent\":",stdout);js(g->extent);fputs(",\"exact_verifier\":",stdout);js(g->verifier);fputs(",\"consumer_ref\":",stdout);js(INTERACTION_CONSUMER);fputs(",\"target_lowerer_ref\":",stdout);js(g->lowerer);fputs(",\"owner_family\":",stdout);js(g->owner_family);fputs(",\"truth\":\"donor_informed_native_grammar_not_donor_backend_or_binding\",\"cannot_infer\":[\"grammar -> a subject, message, media identity, member, right, authority, delivery, payment or effect\",\"owner verifier reference -> verifier executed\",\"consumer handoff -> target lowerer executed\"]}\n",stdout);}
static int cmd_catalog(void){size_t i;fputs("{\"schema\":\"bonfyre-interaction-grammar-catalog.v1\",\"grammar_count\":20,\"grammars\":[",stdout);for(i=0;i<GRAMMAR_COUNT;i++){if(i)putchar(',');fputs("{\"id\":",stdout);js(GRAMMARS[i].id);fputs(",\"donor_reference\":",stdout);js(GRAMMARS[i].donor);fputs(",\"family\":",stdout);js(GRAMMARS[i].family);fputs(",\"owner_family\":",stdout);js(GRAMMARS[i].owner_family);putchar('}');}fputs("],\"truth\":\"closed_grammar_catalog\"}\n",stdout);return 1;}
static int put_binding(sqlite3*d,const char*id,const Grammar*g,const char*subject,const char*institution,const char*owner,const char*visibility,const char*source_kind,const char*source_ref){sqlite3_stmt*s=NULL;int ok=0;if(sqlite3_prepare_v2(d,"INSERT INTO interaction_grammar_binding(binding_id,grammar_id,subject_ref,institution_ref,owner_ref,visibility,state,updated_at,source_kind,source_ref) VALUES(?1,?2,?3,?4,?5,?6,'active',?7,?8,?9) ON CONFLICT(binding_id) DO UPDATE SET grammar_id=excluded.grammar_id,subject_ref=excluded.subject_ref,institution_ref=excluded.institution_ref,owner_ref=excluded.owner_ref,visibility=excluded.visibility,state='active',updated_at=excluded.updated_at,source_kind=excluded.source_kind,source_ref=excluded.source_ref WHERE interaction_grammar_binding.owner_ref=excluded.owner_ref",-1,&s,0)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,id,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,g->id,-1,SQLITE_STATIC);sqlite3_bind_text(s,3,subject,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,4,institution?institution:"",-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,5,owner,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,6,visibility,-1,SQLITE_TRANSIENT);sqlite3_bind_int64(s,7,time(0));sqlite3_bind_text(s,8,source_kind,-1,SQLITE_STATIC);sqlite3_bind_text(s,9,source_ref?source_ref:"",-1,SQLITE_TRANSIENT);ok=sqlite3_step(s)==SQLITE_DONE&&sqlite3_changes(d)==1;sqlite3_finalize(s);return ok;}
static int cmd_bind(sqlite3*d,int ac,char**av){const char*id=arg(ac,av,"--id"),*gid=arg(ac,av,"--grammar"),*subject=arg(ac,av,"--subject"),*institution=arg(ac,av,"--institution"),*owner=arg(ac,av,"--owner"),*visibility=arg(ac,av,"--visibility"),*by=arg(ac,av,"--by");const Grammar*g=grammar(gid);int ok;if(!atom(id)||!g||!atom(subject)||!atom(owner)||!atom(by)||strcmp(by,owner)||!owner_family_matches(g,owner)||!visibility||(strcmp(visibility,"public")&&strcmp(visibility,"member")&&strcmp(visibility,"private")))return 0;if(!institution)institution="";if(*institution&&!atom(institution))return 0;ok=put_binding(d,id,g,subject,institution,owner,visibility,"manual","");if(ok){fputs("{\"schema\":\"bonfyre-interaction-grammar-binding.v1\",\"binding_id\":",stdout);js(id);fputs(",\"grammar_id\":",stdout);js(gid);fputs(",\"owner_family\":",stdout);js(g->owner_family);fputs(",\"source_kind\":\"manual\",\"state\":\"active\",\"truth\":\"family_matched_binding_not_owner_state_or_authority\"}\n",stdout);}return ok;}
/* Canonical-owner bindings are derived only after reading the active native
 * owner row.  They are still forwarding declarations: caller-specific
 * visibility and playback are rechecked by the owner later. */
static const char*grammar_visibility(const char*v){return !strcmp(v,"public")?"public":!strcmp(v,"private")?"private":"member";}
static int cmd_bind_channel(sqlite3*d,int ac,char**av){const char*id=arg(ac,av,"--id"),*gid=arg(ac,av,"--grammar"),*path=arg(ac,av,"--creator-channel-db"),*channel=arg(ac,av,"--channel"),*by=arg(ac,av,"--by");sqlite3*c=0;sqlite3_stmt*s=0;const Grammar*g=grammar(gid);char owner[512],source_owner[512]={0},visibility[32]={0},institution[512]={0};int ok=0;if(!atom(id)||!g||!path||!atom(channel)||!atom(by)||(strcmp(gid,"youtube-creator-channel")&&strcmp(gid,"tiktok-short-stream")))return 0;if(sqlite3_open_v2(path,&c,SQLITE_OPEN_READONLY,0)!=SQLITE_OK)goto out;if(sqlite3_prepare_v2(c,"SELECT owner_subject,visibility,COALESCE(community_ref,'') FROM creator_channel WHERE channel_id=?1 AND state='active'",-1,&s,0)!=SQLITE_OK)goto out;sqlite3_bind_text(s,1,channel,-1,SQLITE_TRANSIENT);if(sqlite3_step(s)!=SQLITE_ROW||!sqlite3_column_text(s,0)||!sqlite3_column_text(s,1))goto out;snprintf(source_owner,sizeof(source_owner),"%s",sqlite3_column_text(s,0));snprintf(visibility,sizeof(visibility),"%s",sqlite3_column_text(s,1));snprintf(institution,sizeof(institution),"%s",sqlite3_column_text(s,2)?(const char*)sqlite3_column_text(s,2):"");sqlite3_finalize(s);s=0;if(strcmp(by,source_owner)||snprintf(owner,sizeof(owner),"CreatorChannel:%s",channel)>=(int)sizeof(owner))goto out;ok=put_binding(d,id,g,channel,institution,owner,grammar_visibility(visibility),"creator_channel",channel);if(ok){fputs("{\"schema\":\"bonfyre-interaction-grammar-owner-binding.v1\",\"binding_id\":",stdout);js(id);fputs(",\"grammar_id\":",stdout);js(gid);fputs(",\"owner_ref\":",stdout);js(owner);fputs(",\"source_kind\":\"creator_channel\",\"source_ref\":",stdout);js(channel);fputs(",\"truth\":\"active_creator_channel_owner_row_bound_not_actor_visibility_or_playback\"}\n",stdout);}
out:if(s)sqlite3_finalize(s);if(c)sqlite3_close(c);return ok;}
static int cmd_bind_library(sqlite3*d,int ac,char**av){const char*id=arg(ac,av,"--id"),*gid=arg(ac,av,"--grammar"),*path=arg(ac,av,"--media-library-db"),*library=arg(ac,av,"--library"),*by=arg(ac,av,"--by");sqlite3*c=0;sqlite3_stmt*s=0;const Grammar*g=grammar(gid);char owner[512],source_owner[512]={0},visibility[32]={0};int ok=0;if(!atom(id)||!g||!path||!atom(library)||!atom(by)||strcmp(gid,"spotify-audio-habitat"))return 0;if(sqlite3_open_v2(path,&c,SQLITE_OPEN_READONLY,0)!=SQLITE_OK)goto out;if(sqlite3_prepare_v2(c,"SELECT owner_subject,visibility FROM media_library WHERE library_id=?1 AND state='active'",-1,&s,0)!=SQLITE_OK)goto out;sqlite3_bind_text(s,1,library,-1,SQLITE_TRANSIENT);if(sqlite3_step(s)!=SQLITE_ROW||!sqlite3_column_text(s,0)||!sqlite3_column_text(s,1))goto out;snprintf(source_owner,sizeof(source_owner),"%s",sqlite3_column_text(s,0));snprintf(visibility,sizeof(visibility),"%s",sqlite3_column_text(s,1));sqlite3_finalize(s);s=0;if(strcmp(by,source_owner)||snprintf(owner,sizeof(owner),"MediaLibrary:%s",library)>=(int)sizeof(owner))goto out;ok=put_binding(d,id,g,library,"",owner,grammar_visibility(visibility),"media_library",library);if(ok){fputs("{\"schema\":\"bonfyre-interaction-grammar-owner-binding.v1\",\"binding_id\":",stdout);js(id);fputs(",\"grammar_id\":",stdout);js(gid);fputs(",\"owner_ref\":",stdout);js(owner);fputs(",\"source_kind\":\"media_library\",\"source_ref\":",stdout);js(library);fputs(",\"truth\":\"active_media_library_owner_row_bound_not_actor_access_or_listen_right\"}\n",stdout);}
out:if(s)sqlite3_finalize(s);if(c)sqlite3_close(c);return ok;}
static int cmd_retire(sqlite3*d,int ac,char**av){const char*id=arg(ac,av,"--id"),*by=arg(ac,av,"--by");sqlite3_stmt*s=NULL;int ok;if(!atom(id)||!atom(by)||sqlite3_prepare_v2(d,"UPDATE interaction_grammar_binding SET state='retired',updated_at=?1 WHERE binding_id=?2 AND owner_ref=?3 AND state='active'",-1,&s,NULL)!=SQLITE_OK)return 0;sqlite3_bind_int64(s,1,time(NULL));sqlite3_bind_text(s,2,id,-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,3,by,-1,SQLITE_TRANSIENT);ok=sqlite3_step(s)==SQLITE_DONE&&sqlite3_changes(d)==1;sqlite3_finalize(s);if(ok){fputs("{\"binding_id\":",stdout);js(id);fputs(",\"state\":\"retired\",\"truth\":\"retired_binding_no_longer_advertisable\"}\n",stdout);}return ok;}
static int cmd_surface(sqlite3*d,int ac,char**av){const char*id=arg(ac,av,"--binding");sqlite3_stmt*s=NULL;const Grammar*g;int ok=0;if(!atom(id)||sqlite3_prepare_v2(d,"SELECT grammar_id,subject_ref,institution_ref,owner_ref,visibility FROM interaction_grammar_binding WHERE binding_id=?1 AND state='active'",-1,&s,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,id,-1,SQLITE_TRANSIENT);if(sqlite3_step(s)==SQLITE_ROW&&(g=grammar((const char*)sqlite3_column_text(s,0)))!=NULL){fputs("{\"schema\":\"bonfyre-interaction-surface-plan.v1\",\"binding_id\":",stdout);js(id);fputs(",\"grammar\":",stdout);js(g->id);fputs(",\"subject_ref\":",stdout);js((const char*)sqlite3_column_text(s,1));fputs(",\"institution_ref\":",stdout);js((const char*)sqlite3_column_text(s,2));fputs(",\"owner_ref\":",stdout);js((const char*)sqlite3_column_text(s,3));fputs(",\"visibility\":",stdout);js((const char*)sqlite3_column_text(s,4));fputs(",\"application\":",stdout);js(g->application);fputs(",\"operation\":",stdout);js(g->operation);fputs(",\"extent\":",stdout);js(g->extent);fputs(",\"exact_verifier\":",stdout);js(g->verifier);fputs(",\"consumer_ref\":",stdout);js(INTERACTION_CONSUMER);fputs(",\"target_lowerer_ref\":",stdout);js(g->lowerer);fputs(",\"exact_verifier_state\":\"UNQUERIED\",\"truth\":\"compiled_surface_plan_not_owner_result_or_rendered_surface\"}\n",stdout);ok=1;}sqlite3_finalize(s);return ok;}
static int cmd_ads(sqlite3*d){sqlite3_stmt*s=NULL;int n=0;if(sqlite3_prepare_v2(d,"SELECT binding_id,grammar_id,subject_ref,institution_ref,owner_ref,visibility FROM interaction_grammar_binding WHERE state='active' ORDER BY binding_id",-1,&s,NULL)!=SQLITE_OK)return 0;while(sqlite3_step(s)==SQLITE_ROW){const char*id=(const char*)sqlite3_column_text(s,0),*gid=(const char*)sqlite3_column_text(s,1),*subject=(const char*)sqlite3_column_text(s,2),*institution=(const char*)sqlite3_column_text(s,3),*owner=(const char*)sqlite3_column_text(s,4),*visibility=(const char*)sqlite3_column_text(s,5);const Grammar*g=grammar(gid);int first=1;if(!id||!g||!subject||!owner||!visibility)continue;fputs("{\"identity\":\"interaction-grammar:",stdout);fputs(id,stdout);fputs("\",\"candidate_kind\":\"interaction_grammar\",\"owner_ref\":",stdout);js(owner);fputs(",\"exact_verifier\":",stdout);js(g->verifier);fputs(",\"lowerer_ref\":",stdout);js(INTERACTION_CONSUMER);fputs(",\"validity_frontier\":\"interaction-grammar:",stdout);fputs(id,stdout);fputs("\",\"terms\":[",stdout);term(&first,"subject",subject);term(&first,"grammar",g->id);term(&first,"application",g->application);term(&first,"operation",g->operation);term(&first,"extent",g->extent);term(&first,"audience",visibility);if(institution&&*institution)term(&first,"institution",institution);fputs("],\"dependencies\":[\"interaction-grammar:",stdout);fputs(id,stdout);fputs("\",",stdout);js(owner);fputs(",\"interaction-grammar-basis:",stdout);fputs(g->id,stdout);fputs("\"]}\n",stdout);n++;}sqlite3_finalize(s);fprintf(stderr,"{\"schema\":\"bonfyre-interaction-grammar-advertisements.v1\",\"emitted\":%d,\"truth\":\"forwarding_descriptors_to_native_consumer_only\"}\n",n);return 1;}
static void usage(void){fputs("bonfyre-interaction-grammar catalog\n  bonfyre-interaction-grammar describe --grammar ID\n  bonfyre-interaction-grammar bind --db FILE --id ID --grammar ID --subject SUBJECT [--institution SUBJECT] --owner OWNER --visibility public|member|private --by OWNER  # internal owner/compiler path\n  bonfyre-interaction-grammar bind-creator-channel --db FILE --id ID --grammar youtube-creator-channel|tiktok-short-stream --creator-channel-db FILE --channel ID --by OWNER_SUBJECT\n  bonfyre-interaction-grammar bind-media-library --db FILE --id ID --grammar spotify-audio-habitat --media-library-db FILE --library ID --by OWNER_SUBJECT\n  bonfyre-interaction-grammar retire --db FILE --id ID --by OWNER\n  bonfyre-interaction-grammar surface --db FILE --binding ID\n  bonfyre-interaction-grammar emit-advertisements --db FILE\n",stderr);}
int main(int ac,char**av){const char*dbp=arg(ac,av,"--db"),*gid=arg(ac,av,"--grammar");sqlite3*d=NULL;int ok=0;if(ac<2){usage();return 2;}if(!strcmp(av[1],"catalog"))return cmd_catalog()?0:1;if(!strcmp(av[1],"describe")){const Grammar*g=grammar(gid);if(!g)return 1;print_grammar(g);return 0;}if(!dbp){usage();return 2;}if(!open_db(dbp,&d))return 1;if(!strcmp(av[1],"bind"))ok=cmd_bind(d,ac,av);else if(!strcmp(av[1],"bind-creator-channel"))ok=cmd_bind_channel(d,ac,av);else if(!strcmp(av[1],"bind-media-library"))ok=cmd_bind_library(d,ac,av);else if(!strcmp(av[1],"retire"))ok=cmd_retire(d,ac,av);else if(!strcmp(av[1],"surface"))ok=cmd_surface(d,ac,av);else if(!strcmp(av[1],"emit-advertisements"))ok=cmd_ads(d);else usage();sqlite3_close(d);return ok?0:1;}
